+        const center = window.innerHeight / 2;
+        let bestIdx = 0;
+        let bestDist = Infinity;
+        this.slides.forEach((slide, idx) => {
+          const rect = slide.getBoundingClientRect();
+          const slideCenter = rect.top + rect.height / 2;
